{
  "name": "set_scan_params",
  "confidence": "medium",
  "docstring": "Debug command handler that parses two decimal arguments, toggles GPIOs to select a table/mode pair, and logs the resulting table and mode labels.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "argc",
    "a2": "argv",
    "v4": "mode_arg",
    "v5": "table_arg",
    "v6": "mode_sel",
    "v7": "table_sel",
    "v12": "table_name",
    "v13": "mode_name"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "packed mode label buffer used when mode_sel is nonzero"
    },
    {
      "offset": 2,
      "meaning": "third byte of the mode_sel-true label buffer"
    },
    {
      "offset": 4,
      "meaning": "packed mode label buffer used when mode_sel is zero"
    },
    {
      "offset": 6,
      "meaning": "third byte of the mode_sel-false label buffer"
    },
    {
      "offset": 8,
      "meaning": "packed table label buffer used when table_sel is nonzero"
    },
    {
      "offset": 10,
      "meaning": "third byte of the table_sel-true label buffer"
    },
    {
      "offset": 12,
      "meaning": "packed table label buffer used when table_sel is zero"
    },
    {
      "offset": 14,
      "meaning": "third byte of the table_sel-false label buffer"
    }
  ]
}
